}

// ── components ───────────────────────────────────────────────────────────────────
// Kit + component SUMMARIES (identity/classification/reuse), not the source bodies —
// `srcText`/`props`/rules stay desktop-side where the Design Studio edits them.
//
// `spec` IS THE EXCEPTION, and the distinction is the whole point rather than an
// inconsistency. `srcText` is React source: the phone cannot run it, and shipping it would be
// shipping CODE. A `spec` is a GeneralNode tree — DATA naming primitives the phone already
// implements natively, which its KitRenderer walks. So the summary/body line is not
// "small vs large", it is "can the phone render this without executing anything".
//
// Without this field mobile's `SpecHost` can only ever draw specs bundled INSIDE the mobile
// repo, which inverts the whole arrangement: screens for the phone would be authored in the
// phone's own tree rather than in this graph. Projecting it is what lets a screen the desktop
// authored reach the device, and what makes a live re-render a rev bump rather than a release.
//
// Size is handled, not ignored: an over-cap domain fragments into `store_state_chunk` frames
// (#3757) against the transport's 48 KB plaintext cap, and mobile reassembles them by rev.

export interface ComponentCard {
  id: string;
  name: string;
  kitId: string;
  role: string;
  version: string;
  used: number;
  tags: string[];
  variants: string[];
  composes: string[];
  builtin?: boolean;
  /** The component's declarative layout tree, when it has one (#3485/#3500). ABSENT for a leaf
   *  primitive or a page not migrated to a spec — and absent must stay absent (never `{}`), so a
   *  mobile selector can tell "no spec authored" from "a spec that renders nothing". */
  spec?: GeneralNode;
}

export interface ComponentsPayload {
  kits: Kit[];
  components: ComponentCard[];
  /** Which project consumes which kit (the propagation consumer index). */
  usage: KitConsumer[];
}

export function buildComponentsPayload(input: {
  kits: Kit[];
  components: ComponentRecord[];
  usage: KitConsumer[];
}): ComponentsPayload {
  return {
    kits: input.kits,
    components: input.components.map((c) => ({
      id: c.id, name: c.name, kitId: c.kitId, role: c.role, version: c.version,
      used: c.used, tags: c.tags, variants: c.variants, composes: c.composes,
      builtin: c.builtin,
      // Passed through verbatim rather than pared: the renderer validates the tree against the
      // manifest on arrival, and a partially-projected node would fail that validation as
      // "malformed" instead of as "unsupported", which is a much worse error to debug on a phone.
      spec: c.spec,
    })),
    usage: input.usage,
  };
}

// ── themes ───────────────────────────────────────────────────────────────────────
// The themes registry (the @data/ui/themes.json shape, hydrated into the store) + the active
// kit theme id — mobile consumes the vars as data (same look, native layout).

export interface ThemesPayload {
  themes: KitThemeRecord[];
  active: string;
}

export function buildThemesPayload(input: { themes: KitThemeRecord[]; active: string }): ThemesPayload {
