}

// ── automations ──────────────────────────────────────────────────────────────────
// The automation list with its recent run records (embedded per automation, newest first)
// plus the hooks list. Hook-fire analytics are dropped (analytics are out on mobile).

/** Runs included per automation in the mobile payload (the store itself caps at 25). */
export const AUTOMATION_RUNS_CAP = 10;

export interface AutomationCard {
  id: string;
  name: string;
  armed: boolean;
  when: Automation["when"];
  lastRunAt: number | null;
  nextRunAt: number | null;
  runs: AutomationRun[];
}

export interface HookCard {
  id: string;
  name: string;
  enabled: boolean;
  event: string;
  matcher?: string;
  projects: string[];
}

export interface AutomationsPayload {
  automations: AutomationCard[];
  hooks: HookCard[];
}

export function buildAutomationsPayload(input: {
  automations: Automation[];
  hooks: Hook[];
}): AutomationsPayload {
  return {
    automations: input.automations.map((a) => ({
      id: a.id, name: a.name, armed: a.armed, when: a.when,
      lastRunAt: a.lastRunAt, nextRunAt: a.nextRunAt,
      runs: a.runs.slice(0, AUTOMATION_RUNS_CAP),
    })),
    hooks: input.hooks.map((h) => ({
      id: h.id, name: h.name, enabled: h.enabled, event: h.event,
      matcher: h.matcher, projects: h.projects,
    })),
  };
}

// ── mcp ──────────────────────────────────────────────────────────────────────────
// The MCP server list + which are installed (runnable config present — the same
// `resolveAllInstalledMcp` set the desktop page derives). Env vars stay desktop-side
// (they can carry secrets).

export interface McpCard {
  id: string;
  name: string;
  enabled: boolean;
  transport: string;
  projects: string[];
  url?: string;
  /** The server has a runnable config (in the installed set). */
  installed: boolean;
}

export interface McpPayload {
  servers: McpCard[];
}

export function buildMcpPayload(input: {
  servers: McpServer[];
  /** Ids of the installed set (from `resolveAllInstalledMcp`, which includes built-ins). */
  installedIds: string[];
}): McpPayload {
  const installed = new Set(input.installedIds);
  return {
    servers: input.servers.map((s) => ({
      id: s.id, name: s.name, enabled: s.enabled, transport: s.transport,
      projects: s.projects, url: s.url, installed: installed.has(s.id),
    })),
  };
}

// ── security (#2530 / #3754) ───────────────────────────────────────────────────────
// The least-privilege picture the mobile Security page (#223) renders, READ-ONLY: the always-on
// application roles + the assignable agent profiles (#289 — the permission CONFIG: base policy ·
// command allowlist · per-tool tri-states · write-path scope · network HOST allowlist), a live
// console/pane model, the per-pane role + profile assignments, and recent audit activity (bsc-audit,
// #257). No secrets cross — `net` is a host allowlist (not credentials), and each audit row is a
// short/redacted display row, never a full tool input.
//
// #3754 closes the last mobile-Security gap: the audit `decision` (allow/ask/block) and the
// pane→console join are computed by the DESKTOP's single source of truth (buildAuditRows / the
// launch-gate rules) in the projector, so mobile never re-derives a security verdict.

/** Recent audit rows in the security payload — the desktop log keeps more; mobile shows a phone-sized
 *  window. Sized so the payload (re-pushed every 15s, each row now a full display row rather than a raw
 *  record) stays comfortably under the Noise transport's per-message cap (#3754). */
export const SECURITY_AUDIT_CAP = 50;

export interface SecurityProfileCard {
  id: string;
  name: string;
  category: string;
  desc: string;
  /** Base policy for anything not explicitly listed (deny | ask | allow). */
  mode: string;
  commands: string[];
  /** tool → tier (read/edit/bash/… → deny|ask|allow). */
  tools: Record<string, string>;
  paths: { allow: string[]; deny: string[] };
  /** Allowed network hosts — NOT credentials. */
  net: string[];
  builtin?: boolean;
  /** Swatch colour for the profile chip (#3754). */
  color: string;
  /** "built-in" | "user-defined" | "generated by Planner" — the origin chip (#3754). */
  origin?: string;
  // Application-role only (#3754): present on {@link SecurityPayload.appRoles}, undefined (dropped from
  // the wire JSON) on a plain assignable profile.
  surface?: string;
  surfaceGlyph?: string;
  session?: string;
  owns?: string;
}

/** A console summary (#3754): the INPUTS mobile needs to render "console / pane" and compute a pane's
 *  effective allowlist locally (guaranteed ∪ profile ∪ project ∪ repo — a plain set-merge, not policy
 *  logic). We send the inputs, not the resolved list; only the audit `decision` is desktop-authoritative. */
export interface SecurityConsoleCard {
  id: string;
  name: string;
  repo: string;
  projectAllow: string[];
  repoAllow?: string[];
  panes: { id: string; profileId: string }[];
}

export interface SecurityPayload {
  /** The always-on application singletons (Project Planner, …) the desktop lists FIRST. */
  appRoles: SecurityProfileCard[];
  profiles: SecurityProfileCard[];
  /** Live console/pane model — lets mobile resolve pane→console and the effective allowlist locally. */
  consoles: SecurityConsoleCard[];
  /** paneId → the SessionRole it launched under. Transient — empty before any fleet launch. */
  paneRoles: Record<string, string>;
  /** paneId → assigned agent-profile id. */
  paneProfiles: Record<string, string>;
  /** Recent audit DISPLAY rows (bsc-audit #257 → buildAuditRows), newest first, capped at
   *  {@link SECURITY_AUDIT_CAP}. Each carries the desktop-computed `decision` (allow/ask/block). */
  audit: AuditDisplayRow[];
}

/** Map an AgentProfile to its wire card — the permission config plus the swatch/origin and the
 *  app-role-only fields (undefined on a plain profile, so `JSON.stringify` drops them). */
function toSecurityProfileCard(p: AgentProfile): SecurityProfileCard {
  return {
    id: p.id, name: p.name, category: p.category, desc: p.desc, mode: p.mode,
    commands: p.commands,
    tools: Object.fromEntries(Object.entries(p.tools)),
    paths: { allow: p.paths.allow, deny: p.paths.deny },
    net: p.net.allow,
    builtin: p.builtin,
    color: p.color,
    origin: p.origin,
    surface: p.surface,
    surfaceGlyph: p.surfaceGlyph,
    session: p.session,
    owns: p.owns,
  };
}

export function buildSecurityPayload(input: {
  /** APP_ROLES — the always-on application singletons (rendered first). */
  appRoles: AgentProfile[];
  /** The assignable permission profiles (`s.agentProfiles`). */
  profiles: AgentProfile[];
  /** The live console/pane model, `deriveConsoles(...)` in the projector. */
  consoles: ConsoleSession[];
  paneRoles: Record<string, string>;
  paneProfiles: Record<string, string>;
  /** Pre-computed display rows (`buildAuditRows(...)` in the projector) — carry the desktop `decision`. */
  auditRows: AuditDisplayRow[];
}): SecurityPayload {
  return {
    appRoles: input.appRoles.map(toSecurityProfileCard),
    profiles: input.profiles.map(toSecurityProfileCard),
    consoles: input.consoles.map((c) => ({
      id: c.id, name: c.name, repo: c.repo,
      projectAllow: c.projectAllow,
      repoAllow: c.repoAllow,
      panes: c.panes.map((p) => ({ id: p.id, profileId: p.profileId })),
    })),
    paneRoles: input.paneRoles,
    paneProfiles: input.paneProfiles,
    audit: input.auditRows.slice(0, SECURITY_AUDIT_CAP),
  };
}

